package com.cpf.starter.notification.sms.spi;import java.util.Optional;import java.util.concurrent.ConcurrentHashMap;public final class CpfSmsDispatcher {private final CpfSmsProvider provider;private final ConcurrentHashMap<String,CpfSmsProvider.SubmitResult> results=new ConcurrentHashMap<>();public CpfSmsDispatcher(CpfSmsProvider p){provider=p;}public CpfSmsProvider.SubmitResult send(String recipient,String text,String idempotencyKey){if(idempotencyKey==null||idempotencyKey.isBlank())throw new IllegalArgumentException("SMS idempotencyKey is required");return results.computeIfAbsent(idempotencyKey,k->{try{return provider.submit(recipient,text,k);}catch(RuntimeException ex){return new CpfSmsProvider.SubmitResult("UNKNOWN_RESULT",null,ex.getClass().getSimpleName());}});}public void receipt(String idempotencyKey,String status,String providerMessageId){results.compute(idempotencyKey,(k,v)->new CpfSmsProvider.SubmitResult(status,providerMessageId,v==null?null:v.detail()));}public Optional<CpfSmsProvider.SubmitResult> result(String key){return Optional.ofNullable(results.get(key));}}
